import java.util.*;

class Solution {
    public int invertBits(int n) {
        int result = n;

        for (int position = 0; position < Integer.SIZE; position++) {
            if (((result >> position) & 1) == 1) {
                result &= ~(1 << position);
            } else {
                result |= (1 << position);
            }
        }

        return result;
    }
}
